fun inSampleSize(w: Int, h: Int, reqW: Int, reqH: Int): Int {
    var size = 1
    if (h > reqH || w > reqW) {
        val halfH = h / 2
        val halfW = w / 2
        while (halfH / size >= reqH && halfW / size >= reqW) {
            size *= 2
        }
    }
    return size
}

fun main() {
    println(inSampleSize(4000, 3000, 500, 500))
    println(inSampleSize(400, 300, 500, 500))
}

